style.css:
@-moz-document domain("facebook.com") {
/* Thêm hình nền cho toàn bộ trang */
  body {
    background-image: url('https://t4.ftcdn.net/jpg/03/86/82/73/240_F_386827376_uWOOhKGk6A4UVL5imUBt20Bh8cmODqzx.jpg');
    background-size: cover !important; /* Đảm bảo hình ảnh phủ toàn bộ trang */
    background-position: center !important; /* Căn giữa hình ảnh */
    background-attachment: fixed !important; /* Hình nền không di chuyển khi cuộn trang */
  }

  /* Thêm hiệu ứng mờ cho nội dung để làm chữ dễ đọc hơn */
  .fb_content {
    background-color: rgba(255, 255, 255, 0.8) !important; /* Nền mờ cho nội dung */
  }

  /* Thay đổi màu chữ để nổi bật trên nền hình ảnh */
  ._5vwz, ._5v5g, ._1xch, ._1xck {
    color: #333 !important; /* Màu chữ đậm */
  }

  /* Thay đổi màu nền của thanh điều hướng để dễ nhìn */
  ._1vp5, ._1xv7 {
    background-color: rgba(255, 255, 255, 0.9) !important;
  }

  /* Chỉnh sửa các liên kết để dễ đọc hơn */
  a {
    color: #0066cc !important; /* Màu liên kết */
  }
}
